// Package licences is the licence text of Jaggery and of everything built
// into jag: Go and each module. Some of those licences ask that a copy of the
// program carries their notice; jag licences prints this text.
//
// licences.txt is generated by scripts/gen-licences.sh, and CI checks it
// matches go.mod.
package licences

import _ "embed"

//go:embed licences.txt
var Text string
